            className="absolute bottom-0 left-0 right-0 h-[2px] bg-gradient-to-r from-transparent via-blue-400/50 to-transparent"
            initial={{ opacity: 0, scaleX: 0 }}
            animate={{ opacity: 1, scaleX: 1 }}
            transition={{ duration: 0.5, ease: "easeOut" }}
          />
        )}
      </AnimatePresence>

      {/* ── Floating share-on-X popup ── */}
      <AnimatePresence>
        {(isPreConfirmed || isConfirmed) && elapsedSec && (
          <motion.button
            type="button"
            initial={{ opacity: 0, y: 4, scale: 0.9 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 4, scale: 0.9 }}
            transition={{ delay: SHARE_POPUP_DELAY_S, duration: 0.4, ease: [0.2, 0.8, 0.2, 1] }}
            onClick={(e) => {
              e.stopPropagation()
              const tweet = `Just swapped on @Fast_Protocol — preconfirmed in ${elapsedSec}s\n\nhttps://fastprotocol.xyz`
              window.open(
                `https://twitter.com/intent/tweet?text=${encodeURIComponent(tweet)}`,
                "_blank"
              )
            }}
            className="absolute -bottom-3 left-1/2 -translate-x-1/2 z-20 flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-neutral-800 border border-white/10 shadow-lg hover:bg-neutral-700 hover:border-white/20 transition-colors"
          >
            <FaXTwitter className="h-3 w-3 text-neutral-300" />
            <span className="text-[11px] font-medium text-neutral-300">Share</span>
          </motion.button>
        )}
      </AnimatePresence>
    </motion.div>
  )
}

/**
 * Short synthesized "whoosh + chime" sound for preconfirmation.
 * Uses Web Audio API — no external files, instant playback.
 * Respects user's system; only plays once per call.
 */

let audioCtx: AudioContext | null = null

function getAudioContext(): AudioContext | null {
  if (typeof window === "undefined") return null
  if (!audioCtx) {
    try {
      audioCtx = new AudioContext()
    } catch {
      return null
    }
  }
  return audioCtx
}

/**
 * Fast "whoosh + rising chime" — ~300ms total.
 * Feels like a quick confirmation ding with velocity.
 */
export function playPreconfirmSound() {
  const ctx = getAudioContext()
  if (!ctx) return

  // Resume if suspended (browser autoplay policy)
  if (ctx.state === "suspended") {
    ctx.resume().catch(() => {})
  }

  const now = ctx.currentTime

  // ── Whoosh: filtered noise sweep ──
  const noiseLength = 0.15
  const noiseBuffer = ctx.createBuffer(1, ctx.sampleRate * noiseLength, ctx.sampleRate)
  const noiseData = noiseBuffer.getChannelData(0)
  for (let i = 0; i < noiseData.length; i++) {
    noiseData[i] = (Math.random() * 2 - 1) * 0.3
  }
  const noise = ctx.createBufferSource()
  noise.buffer = noiseBuffer

  const noiseFilter = ctx.createBiquadFilter()
  noiseFilter.type = "bandpass"
  noiseFilter.frequency.setValueAtTime(2000, now)
  noiseFilter.frequency.exponentialRampToValueAtTime(6000, now + 0.1)
  noiseFilter.Q.value = 0.5

  const noiseGain = ctx.createGain()
  noiseGain.gain.setValueAtTime(0.08, now)
  noiseGain.gain.exponentialRampToValueAtTime(0.01, now + noiseLength)

  noise.connect(noiseFilter)
  noiseFilter.connect(noiseGain)
  noiseGain.connect(ctx.destination)
  noise.start(now)
  noise.stop(now + noiseLength)

  // ── Chime: two quick rising tones ──
  const playTone = (freq: number, start: number, dur: number, vol: number) => {
    const osc = ctx.createOscillator()
    const gain = ctx.createGain()
    osc.type = "sine"
    osc.frequency.setValueAtTime(freq, now + start)
    gain.gain.setValueAtTime(vol, now + start)
    gain.gain.exponentialRampToValueAtTime(0.001, now + start + dur)
    osc.connect(gain)
    gain.connect(ctx.destination)
    osc.start(now + start)
    osc.stop(now + start + dur)
  }

  // Rising two-note chime (C6 → E6)
  playTone(1047, 0.04, 0.18, 0.06)  // C6
  playTone(1319, 0.10, 0.22, 0.08)  // E6
}

