/**
 * Polls the FastRPC /status/{hash} endpoint via the serverless proxy.
 * This queries the mev-commit chain directly for commitment status —
 * much faster than waiting for the mctransactions DB to index.
 *
 * Returns "preconfirmed" if the tx has a commitment, null otherwise.
 */

const REQUEST_TIMEOUT_MS = 3000

export async function fetchFastRpcCommitmentStatus(
  txHash: string,
  abortSignal?: AbortSignal
): Promise<"preconfirmed" | null> {
  const controller = new AbortController()
  const timeoutId = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS)

  if (abortSignal) {
    if (abortSignal.aborted) { clearTimeout(timeoutId); return null }
    abortSignal.addEventListener("abort", () => controller.abort(), { once: true })
  }

  try {
    const response = await fetch(`/api/transaction-status/${txHash}`, {
      signal: controller.signal,
    })

    clearTimeout(timeoutId)

    if (!response.ok) return null

    const data = await response.json()

    // The /status endpoint returns commitment data if it exists.
    // Any successful response with data means the tx has been preconfirmed.
    if (data?.success && data?.data) {
      return "preconfirmed"
    }

    return null
  } catch {
    clearTimeout(timeoutId)
    return null
  }
}

